impl Solution{pub fn delete_duplicates(head:Option<Box<ListNode>>)->Option<Box<ListNode>>{let mut v=vec![];let mut p=head.as_ref();while let Some(n)=p{v.push(n.val);p=n.next.as_ref();}let mut keep=vec![];let mut i=0;while i<v.len(){let mut j=i+1;while j<v.len()&&v[j]==v[i]{j+=1}if j==i+1{keep.push(v[i]);}i=j;}let mut h=None;for &x in keep.iter().rev(){let mut n=Box::new(ListNode::new(x));n.next=h;h=Some(n);}h}}
